SELECT 'MISSING_TABLE' AS kind, e.table_name AS name, NULL::text AS column_name
FROM (SELECT DISTINCT table_name FROM expected) e
WHERE NOT EXISTS (
  SELECT 1 FROM pg_tables t WHERE t.schemaname = 'public' AND t.tablename = e.table_name
)
UNION ALL
SELECT 'MISSING_COLUMN', e.table_name, e.column_name
FROM expected e
JOIN pg_tables t ON t.schemaname = 'public' AND t.tablename = e.table_name
WHERE NOT EXISTS (
  SELECT 1 FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.table_name = e.table_name AND c.column_name = e.column_name
)
ORDER BY 1, 2, 3;
